__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return o}});var o={tela:{titulo:'Mito \xd7 Fuente',subtitulo:'Lo que te contaron \xd7 lo que est\xe1 escrito',mitoDoDia:'MITO DEL D\xcdA',teContaram:'TE CONTARON',fonteDiz:'LA FUENTE DICE',recibo:'RECIBO',anterior:'Anterior',proximo:'Siguiente',compartilhar:'Compartir',voltarAoDia:'Volver al mito del d\xeda',contador:'{n} de {total}',progresso:'Ya revisaste {n} de {total} mitos.',copiado:'Texto copiado \u2014 p\xe9galo donde quieras.',naoCopiou:'No se pudo copiar aqu\xed \u2014 selecciona el texto y c\xf3pialo.',marca:'cosmicguide.cloud'},compartilhar:{teContaram:'Te contaron:',fonteDiz:'La fuente dice:',recibo:'Recibo:'},mitos:{'taro-egito':{oQueTeContaram:'El tarot viene del antiguo Egipto \u2014 es el Libro de Thoth de los faraones.',oQueAFonteDiz:'La idea entera nace en un cap\xedtulo de un libro franc\xe9s de 1781, de Antoine Court de G\xe9belin \u2014 41 a\xf1os antes de que Champollion descifrara los jerogl\xedficos. \xc9l no ten\xeda c\xf3mo leer una sola l\xednea de egipcio. El propio Waite escribi\xf3 en 1911 que no existe ninguna evidencia del origen egipcio.',fonte:'Le Monde primitif, vol. 8, "Du Jeu des Tarots" \u2014 Court de G\xe9belin, 1781',detalhe:'Ese mazo que venden como secreto de los faraones pas\xf3 unos 350 a\xf1os como juego de apuestas en mesas de taberna italiana. La lectura de cartas como la conocemos tiene 245 a\xf1os: naci\xf3 cuando Court de G\xe9belin public\xf3 la tesis egipcia en 1781 \u2014 y dos a\xf1os despu\xe9s Etteilla vendi\xf3 el primer m\xe9todo. El propio Waite, en 1911, escribi\xf3 que no hay ninguna evidencia del origen egipcio.'},superlua:{oQueTeContaram:'"Superluna" es un fen\xf3meno raro que la astronom\xeda anuncia desde siempre.',oQueAFonteDiz:'El t\xe9rmino lo acu\xf1\xf3 un astr\xf3logo, Richard Nolle, en una revista de hor\xf3scopos en 1979. No existe una definici\xf3n astron\xf3mica oficial \u2014 el nombre t\xe9cnico es perigeo-sizigia, y la diferencia de tama\xf1o es imperceptible a simple vista sin una comparaci\xf3n lado a lado.',fonte:'Richard Nolle, revista Dell Horoscope, 1979',detalhe:'Cada titular de "Superluna gigante" anuncia un espect\xe1culo que nadie distingue a simple vista \u2014 la diferencia es de un 14% de di\xe1metro, visible solo en fotos comparadas. La palabra ni siquiera es de la astronom\xeda: quien la acu\xf1\xf3 fue un astr\xf3logo, Richard Nolle, en una revista de hor\xf3scopos en 1979. El t\xe9rmino solo se viraliz\xf3 en 2011.'},'luas-cheias-nomes':{oQueTeContaram:'"Luna del Lobo", "Luna de Fresa"\u2026 son nombres ind\xedgenas milenarios.',oQueAFonteDiz:"La lista est\xe1ndar la public\xf3 el Maine Farmers' Almanac en los a\xf1os 1930 \u2014 una recopilaci\xf3n de fuentes algonquinas, inglesas coloniales y celtas \u2014 y el Old Farmer's Almanac la simplific\xf3 a un nombre por mes. Y describe el ciclo agr\xedcola del noreste de Estados Unidos: al sur del ecuador llega con el hemisferio equivocado.",fonte:"Maine Farmers' Almanac, a\xf1os 1930",detalhe:'F\xedjate que la "Luna de Nieve" de febrero cae en pleno verano si est\xe1s al sur del ecuador \u2014 el nombre lleg\xf3 listo desde el hemisferio de arriba. La lista famosa sali\xf3 de un almanaque agr\xedcola estadounidense de los a\xf1os 1930, una recopilaci\xf3n de fuentes algonquinas, inglesas y celtas simplificada a un nombre por mes.'},'oito-fases':{oQueTeContaram:'Las 8 fases de la Luna, cada una con su significado, son sabidur\xeda milenaria.',oQueAFonteDiz:'La lectura psicol\xf3gica de las ocho fases es de Dane Rudhyar \u2014 formulada en los ocho tipos soli-lunares de The Lunation Cycle (1967), sobre una idea que ven\xeda desarrollando desde los a\xf1os 1930-40 (The Astrology of Personality, 1936). La divisi\xf3n antigua es otra \u2014 Ptolomeo trabaja con cuatro cuartos, y describe cualidades, no personalidad.',fonte:'Dane Rudhyar \u2014 The Astrology of Personality, 1936; The Lunation Cycle, 1967',detalhe:'El carrusel con las ocho fases de la Luna y el "modo de uso" de cada una tiene due\xf1o y acta de nacimiento. Quien formul\xf3 los ocho tipos con lectura psicol\xf3gica fue Dane Rudhyar, en The Lunation Cycle (1967), sobre una idea que ven\xeda desarrollando desde los a\xf1os 1930-40. Los autores antiguos divid\xedan la Luna en cuatro cuartos \u2014 Ptolomeo describ\xeda cualidades, no personalidad.'},'quiromancia-milenar':{oQueTeContaram:'Leer la mano es un arte milenario \u2014 montes, tipos de mano, l\xednea del matrimonio.',oQueAFonteDiz:"El sistema moderno nace en 1843 con D'Arpentigny (La Chirognomonie), toma cuerpo con Heron-Allen (1883) y se vuelve manual con Benham (1900). Y los cuatro tipos de mano por elemento son de Fred Gettings, 1965.",fonte:"La Chirognomonie, D'Arpentigny, 1843 \xb7 The Laws of Scientific Hand Reading, Benham, 1900",detalhe:"La l\xednea del matrimonio que te mostraron en la playa es m\xe1s joven que la fotograf\xeda. El paquete completo \u2014 montes, tipos de mano, l\xedneas con nombre \u2014 se arm\xf3 entre 1843 y 1900, de D'Arpentigny a Benham. Y los cuatro tipos de mano por elemento son de 1965, de Fred Gettings."},'borra-de-cafe':{oQueTeContaram:'Leer la borra del caf\xe9 es una tradici\xf3n turca milenaria, con s\xedmbolos ancestrales.',oQueAFonteDiz:'El caf\xe9 solo llega a Estambul en el siglo XVI \u2014 la pr\xe1ctica no puede ser m\xe1s vieja que la bebida. Y el diccionario de s\xedmbolos (serpiente = enemistad, casa = mudanza) es sal\xf3n brit\xe1nico de fines del siglo XIX, consolidado por Cicely Kent en 1922.',fonte:'Tea-Cup Reading, "A Highland Seer", 1881 \xb7 Cicely Kent, 1922',detalhe:'No hab\xeda forma de que la bisabuela de hace mil a\xf1os leyera la borra del caf\xe9: los primeros caf\xe9s de Estambul son de 1555, y la pr\xe1ctica no puede ser m\xe1s vieja que la bebida. La tabla de s\xedmbolos, con la serpiente queriendo decir enemistad, se arm\xf3 en salones brit\xe1nicos entre 1881 y 1922, como juego de t\xe9 de la tarde.'},'saturno-mestre':{oQueTeContaram:'Saturno es el gran maestro del zod\xedaco, el profesor de las lecciones \u2014 desde siempre.',oQueAFonteDiz:'La lectura de Saturno como maestro y maduraci\xf3n es de Liz Greene, 1976. En las fuentes antiguas Saturno es mal\xe9fico, y la lectura depende de la secta: Valente anota que los mal\xe9ficos bien ubicados indican "las mayores posiciones y \xe9xito".',fonte:'Liz Greene, 1976 \xb7 contrapunto: Vetio Valente, Antolog\xedas, siglo II',detalhe:'El planeta villano se volvi\xf3 profesor, y nadie not\xf3 el cambio. En las fuentes antiguas Saturno es el mal\xe9fico mayor \u2014 y Valente incluso anota que, bien ubicado en su propia secta, indica "las mayores posiciones y \xe9xito". El "gran maestro que trae lecciones" es una relectura psicol\xf3gica publicada por Liz Greene en 1976.'},'karma-astrologia':{oQueTeContaram:'El karma y las vidas pasadas siempre fueron parte de la astrolog\xeda.',oQueAFonteDiz:'No est\xe1n en Ptolomeo, Valente, F\xedrmico, Bonatti ni Lilly. Entran a Occidente por la Teosof\xeda, a partir de 1875, importados del vocabulario indio. Y el Nodo Norte como "misi\xf3n del alma" es de Martin Schulman, 1975.',fonte:'Teosof\xeda, desde 1875 \xb7 Martin Schulman, Karmic Astrology, 1975',detalhe:'La "deuda k\xe1rmica" de la carta no aparece en ning\xfan autor antiguo \u2014 ni en los griegos, ni en los medievales, ni en Lilly. Ese vocabulario entra a la astrolog\xeda occidental por la Teosof\xeda, fundada en 1875. Y el paquete "Nodo Norte = misi\xf3n del alma" es de un libro de 1975, de Martin Schulman.'},'porcentagem-compatibilidade':{oQueTeContaram:'Existe un porcentaje de compatibilidad entre signos \u2014 "ustedes tienen un 87% de match".',oQueAFonteDiz:'El n\xfamero no existe en fuente alguna \u2014 antigua, medieval o renacentista. Revisados Ptolomeo, Doroteo, M\u0101sh\u0101\u02beall\u0101h y Lilly: ninguno. Lo que la tradici\xf3n tiene es una escala de cuatro pelda\xf1os (Tetrabiblos IV.7), y en ella un tercio de los pares de signos es "ajeno".',fonte:'Sin fuente antigua \u2014 invenci\xf3n comercial del siglo XX; la escala real: Ptolomeo, Tetrabiblos IV.7, siglo II',detalhe:'Ese "ustedes combinan 87%" no sali\xf3 de ning\xfan libro \u2014 sali\xf3 de revistas y de software del siglo pasado. En la fuente antigua la regla es otra y m\xe1s dura: Ptolomeo ordena las relaciones en cuatro pelda\xf1os, y a un tercio de los pares de signos los llama ajenos \u2014 ni se ven. La nota baja no vende, y el mercado dej\xf3 de mostrarla.'},'lua-azul':{oQueTeContaram:'"Luna Azul" es la segunda luna llena del mes \u2014 definici\xf3n cl\xe1sica.',oQueAFonteDiz:"Es un error de lectura documentado: en 1946 el astr\xf3nomo aficionado James Hugh Pruett entendi\xf3 mal la regla del Maine Farmers' Almanac en Sky & Telescope (all\xed era la tercera llena de una estaci\xf3n con cuatro). La propia revista se corrigi\xf3 en 1999. Ninguna de las dos definiciones es antigua.",fonte:'Sky & Telescope, James Hugh Pruett, 1946; fe de erratas de la propia revista, 1999',detalhe:'La definici\xf3n que todo el mundo repite naci\xf3 de alguien leyendo mal una revista. En 1946 el astr\xf3nomo aficionado Pruett entendi\xf3 mal la regla del almanaque en Sky & Telescope; NPR la repiti\xf3 en 1980 y el Trivial Pursuit la cristaliz\xf3 en 1986. La propia revista public\xf3 la correcci\xf3n en 1999 \u2014 demasiado tarde.'},'lua-de-sangue':{oQueTeContaram:'"Luna de Sangre" es un t\xe9rmino b\xedblico antiguo para los eclipses.',oQueAFonteDiz:'La imagen existe en Joel 2:31, pero el t\xe9rmino como nombre de eclipse es del pastor Mark Biltz (2008) y de John Hagee (Four Blood Moons, 2013). Los astr\xf3nomos no lo usan.',fonte:'Mark Biltz, 2008 \xb7 John Hagee, Four Blood Moons, 2013',detalhe:'El nombre que estampa cada titular de eclipse es m\xe1s nuevo que el iPhone. Como etiqueta de eclipse lunar, "Luna de Sangre" la lanz\xf3 un pastor estadounidense en 2008 y se volvi\xf3 best seller en 2013. La Biblia tiene la imagen po\xe9tica en Joel \u2014 pero no llama as\xed a los eclipses.'},'mercurio-retrogrado':{oQueTeContaram:'Mercurio retr\xf3grado rompe aparatos, tumba sistemas y hace volver al ex.',oQueAFonteDiz:'La fuente antigua habla de demora: Valente escribe que el retr\xf3grado "pospone expectativas, acciones y ganancias" y que la segunda estaci\xf3n "cancela la demora". Nada de tecnolog\xeda, contratos ni ex. La expresi\xf3n ni siquiera aparece en la prensa general antes de 1996.',fonte:'Vetio Valente, Antolog\xedas, siglo II; rastreo de prensa: 1996',detalhe:'El culpable oficial de la laptop trabada tiene coartada de casi dos mil a\xf1os. Lo que Valente escribi\xf3 en el siglo II fue demora: el retr\xf3grado "pospone expectativas, acciones y ganancias" \u2014 nada de aparatos, contratos ni ex. La expresi\xf3n solo llega a la prensa a partir de 1996.'},'leao-coracao':{oQueTeContaram:'Leo rige el coraz\xf3n \u2014 as\xed est\xe1 en los textos antiguos.',oQueAFonteDiz:'En la lista antigua del Hombre Zodiacal (Manilio, Astronomica II), a Leo le tocan los flancos y los om\xf3platos \u2014 el coraz\xf3n es del Sol, no del signo. La versi\xf3n "Leo = coraz\xf3n" imprimible m\xe1s antigua es la Escala del Doce de Agrippa, 1533.',fonte:'Manilio, Astronomica II.453\u2013465, siglo I \xb7 Agrippa, 1533',detalhe:'Pregunta en cualquier grupo de astrolog\xeda de d\xf3nde viene el "Leo rige el coraz\xf3n" y nadie se\xf1ala el libro. En la lista m\xe1s antigua de cuerpo y signo, Manilio le da a Leo los flancos y los om\xf3platos \u2014 el coraz\xf3n pertenec\xeda al Sol. La versi\xf3n popular solo aparece impresa en 1533, en la Escala del Doce de Agrippa.'},ofiuco:{oQueTeContaram:'Existe un 13.\xba signo, Ofiuco, que te esconden.',oQueAFonteDiz:'Signo nunca fue constelaci\xf3n. El zod\xedaco es de doce partes iguales de 30\xb0 desde el siglo V a.C., y Ptolomeo (Tetrabiblos I.22) dice que los signos se cuentan a partir de los equinoccios y solsticios "y de ninguna otra fuente". Los l\xedmites de constelaci\xf3n de la IAU son de 1930.',fonte:'Ptolomeo, Tetrabiblos I.22, siglo II \xb7 l\xedmites de constelaci\xf3n de la IAU, 1930',detalhe:'Cada tanto vuelve el mismo titular: "la NASA cambi\xf3 tu signo". Solo que el signo es una tajada de 30\xb0 contada desde el equinoccio, no un dibujo de constelaci\xf3n \u2014 es as\xed desde hace unos 2.450 a\xf1os, y Ptolomeo escribi\xf3 que los signos se cuentan desde los equinoccios "y de ninguna otra fuente". El mapa de constelaciones que aloja a Ofiuco lo dibuj\xf3 la IAU en 1930, para uso astron\xf3mico.'},'urano-aquario':{oQueTeContaram:'Urano rige Acuario \u2014 regencia cl\xe1sica.',oQueAFonteDiz:'Urano fue descubierto en 1781. En la tradici\xf3n, Acuario es domicilio de Saturno (Ptolomeo, Tetrabiblos I.17). La atribuci\xf3n a Urano empieza en 1825 (Smith) y 1828 (Varley) \u2014 y en 1834 todav\xeda se discut\xeda.',fonte:'Ptolomeo, Tetrabiblos I.17, siglo II; atribuci\xf3n a Urano: Smith, 1825 / Varley, 1828',detalhe:'El "regente cl\xe1sico" de Acuario ni siquiera exist\xeda en los mapas hasta hace nada: Urano solo fue descubierto en 1781. En la tradici\xf3n, Acuario siempre fue casa de Saturno. El cambio empieza alrededor de 1825 \u2014 y en 1834 todav\xeda hab\xeda lectores de almanaque preguntando por qu\xe9 el planeta nuevo no ten\xeda casa.'},'estrela-esperanca':{oQueTeContaram:'La carta de la Estrella siempre fue la carta de la esperanza.',oQueAFonteDiz:'En el manual del propio mazo (Waite, 1911), la primera lectura de la Estrella es "p\xe9rdida, robo, privaci\xf3n, abandono" \u2014 la esperanza aparece como segunda lectura, "otra versi\xf3n". La prioridad se invirti\xf3 a lo largo del siglo XX.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'Abre el manual original del mazo m\xe1s vendido del mundo y busca la Estrella: la primera lectura es "p\xe9rdida, robo, privaci\xf3n, abandono". La esperanza est\xe1 ah\xed como "otra versi\xf3n", en segundo lugar. Fue el siglo XX el que ascendi\xf3 la segunda opci\xf3n a significado \xfanico \u2014 siguiendo la imagen, no el texto.'},'carta-invertida':{oQueTeContaram:'Carta invertida quiere decir bloqueo o negaci\xf3n \u2014 lectura tradicional.',oQueAFonteDiz:'En Waite (1911) la invertida suele ser un significado lateral \u2014 a veces mejor que el de la carta derecha: la Rueda de la Fortuna invertida es "aumento, abundancia"; el Emperador invertido es "benevolencia, compasi\xf3n, cr\xe9dito". La clave "bloqueo/exceso" es del siglo XX (Gray, Pollack, Greer).',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'Hay cartas que mejoran patas arriba en el manual original: la Rueda de la Fortuna invertida se vuelve "aumento, abundancia", y el Emperador invertido, "benevolencia, compasi\xf3n". En Waite, 1911, la invertida suele ser un significado lateral \u2014 no un defecto de la carta. La regla "invertida = bloqueo" se escribi\xf3 despu\xe9s, a lo largo del siglo XX.'},'cruz-celta':{oQueTeContaram:'La Cruz Celta es un m\xe9todo c\xe9ltico ancestral de tirada.',oQueAFonteDiz:'El nombre es de Waite, 1911. La estructura viene de c\xedrculos de la Golden Dawn de los a\xf1os 1890 \u2014 y Waite dice apenas que la tirada "se ha usado en privado por muchos a\xf1os".',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'La tirada m\xe1s famosa del tarot no tiene nada de druida. El nombre "Cruz Celta" se estrena en 1911, en el manual de Waite, y el dise\xf1o viene de los c\xedrculos ocultistas de Londres de los a\xf1os 1890. De celta, solo el bautizo.'},'marselha-o-mais-antigo':{oQueTeContaram:'El Tarot de Marsella es el tarot original, el m\xe1s antiguo de todos.',oQueAFonteDiz:'Es un patr\xf3n de impresi\xf3n franc\xe9s de los siglos XVII\u2013XVIII (Noblet c. 1650, Conver 1760). Los tarots m\xe1s antiguos son los italianos pintados a mano del siglo XV. Y el nombre "Tarot de Marsella" lo populariz\xf3 Paul Marteau, del fabricante Grimaud, en 1930.',fonte:'Patr\xf3n franc\xe9s, siglos XVII\u2013XVIII (Conver, 1760); el nombre: Paul Marteau, Grimaud, 1930',detalhe:'El "tarot original" es m\xe1s nuevo que los mazos a los que dice anteceder: los tarots italianos pintados a mano vienen primero, y el patr\xf3n de Marsella es impresi\xf3n francesa de los siglos XVII\u2013XVIII. Hasta el nombre es etiqueta comercial: quien bautiz\xf3 "Tarot de Marsella" fue el fabricante Paul Marteau, en 1930.'},'astrologia-5000-anos':{oQueTeContaram:'La astrolog\xeda tiene 5.000 a\xf1os.',oQueAFonteDiz:'Lo que tiene ~4.000 a\xf1os son presagios de Estado mesopot\xe1micos \u2014 otra cosa. El zod\xedaco tiene ~2.450 a\xf1os; el hor\xf3scopo individual m\xe1s antiguo es del 410 a.C.; la carta natal con Ascendente y casas tiene ~2.150 a\xf1os.',fonte:'Hor\xf3scopo cuneiforme m\xe1s antiguo: 410 a.C.; carta natal helen\xedstica: c. 150\u2013120 a.C.',detalhe:'El n\xfamero redondo duplica la edad real de la cosa. Lo que los babilonios de hace 4.000 a\xf1os le\xedan era presagio de Estado \u2014 lluvia, guerra, rey \u2014 y no carta de persona. El primer hor\xf3scopo individual conocido es del 410 a.C., y la carta natal con Ascendente y casas tiene unos 2.150 a\xf1os.'},'horoscopo-de-jornal':{oQueTeContaram:'El hor\xf3scopo diario por signo es el formato cl\xe1sico de la astrolog\xeda.',oQueAFonteDiz:'Tiene fecha de estreno: 24 de agosto de 1930, en el Sunday Express, por R. H. Naylor \u2014 sobre el nacimiento de la princesa Margaret. En 1930 el diario tuvo que explicarles a los lectores qu\xe9 era un hor\xf3scopo.',fonte:'R. H. Naylor, Sunday Express, 24/08/1930',detalhe:'El hor\xf3scopo de tu feed tiene fecha de estreno como una telenovela: agosto de 1930, en un diario brit\xe1nico, sobre el nacimiento de una princesa. Era tanta la novedad que el diario tuvo que explicarles a los lectores qu\xe9 era un hor\xf3scopo. En la tradici\xf3n, lo que describe al individuo es el Ascendente, no el signo solar.'},'signo-personalidade':{oQueTeContaram:'"Aries es impulsivo, Escorpio es intenso" \u2014 los antiguos ya los describ\xedan as\xed.',oQueAFonteDiz:'La caracterolog\xeda por signo solar es del siglo XX: Alan Leo (c. 1895\u20131910) en adelante, popularizada por Linda Goodman en 1968. En Ptolomeo, el car\xe1cter viene de Mercurio y de la Luna (Tetrabiblos III.13) \u2014 no existe un cap\xedtulo de "doce personalidades".',fonte:'Alan Leo, c. 1895\u20131910 \xb7 Linda Goodman, Sun Signs, 1968 \xb7 Ptolomeo, Tetrabiblos III.13, siglo II',detalhe:'El retrato hablado de tu signo \u2014 terco, dram\xe1tico, so\xf1ador \u2014 no est\xe1 en ning\xfan autor antiguo. Ese formato nace con Alan Leo en el cambio al siglo XX y explota con Linda Goodman en 1968. Ptolomeo le\xeda el car\xe1cter en Mercurio y en la Luna; y el retrato que Valente hace de los signos es irreconocible para quien lee hor\xf3scopos hoy.'},'numerologia-pitagoras':{oQueTeContaram:'La tabla numerol\xf3gica A=1, B=2\u2026 viene de Pit\xe1goras.',oQueAFonteDiz:'Pit\xe1goras no dej\xf3 ning\xfan escrito, y el alfabeto de 26 letras no es el suyo. La tabla en tres columnas de nueve es rastreable hasta L. Dow Balliett, 1908 \u2014 los "n\xfameros maestros" 11 y 22 tambi\xe9n son de ella.',fonte:'L. Dow Balliett, 1908',detalhe:'El "m\xe9todo de Pit\xe1goras" usa un alfabeto que Pit\xe1goras nunca vio \u2014 y \xe9l no dej\xf3 ning\xfan escrito. La tabla de tres filas con el alfabeto moderno tiene su rastro m\xe1s antiguo en un libro de 1908, de L. Dow Balliett, junto con los n\xfameros maestros 11 y 22. De griego, qued\xf3 el nombre.'},'lua-nova-intencoes':{oQueTeContaram:'La Luna Nueva es el momento de sembrar intenciones \u2014 ritual ancestral.',oQueAFonteDiz:'Sembrar DE VERDAD en la luna oscura es fuente primaria: Cat\xf3n, siglo II a.C., "luna silente". "Sembrar intenciones" es transposici\xf3n moderna \u2014 Jan Spiller, New Moon Astrology, 2001.',fonte:'Cat\xf3n, De Agri Cultura 40.1, siglo II a.C. \xb7 Jan Spiller, New Moon Astrology, 2001',detalhe:'La parte de sembrar es romana; la parte de la lista de deseos tiene la edad de Windows XP. Cat\xf3n mandaba sembrar con la luna oscura \u2014 siembra de verdad, en el suelo. El cuaderno de intenciones de Luna Nueva es de un libro estadounidense de 2001, de Jan Spiller.'},'nao-e-previsao':{oQueTeContaram:'"No es predicci\xf3n, son tendencias" \u2014 el marco elegante de siempre de la astrolog\xeda.',oQueAFonteDiz:'La frase nace de una defensa penal: Alan Leo fue procesado por adivinaci\xf3n en Londres en 1914 y 1917; la tesis de la defensa era que \xe9l describ\xeda tendencias, no fortunas. Se derrumb\xf3 cuando la fiscal\xeda ley\xf3 su almanaque prediciendo una muerte en la familia \u2014 fue condenado y multado con \xa35.',fonte:'Procesos de Alan Leo, Londres, 1914 y 1917',detalhe:'La frase m\xe1s elegante del mercado naci\xf3 en un tribunal. Alan Leo, procesado por adivinaci\xf3n en Londres, se defendi\xf3 diciendo que describ\xeda tendencias, no fortunas \u2014 la fiscal\xeda ley\xf3 en voz alta su almanaque prediciendo una muerte en la familia, y fue condenado en 1917. El mercado entero hered\xf3 la frase sin saber de d\xf3nde vino.'}}}},1633,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return t}});var t={tela:{titulo:'Myth \xd7 Source',subtitulo:'What you were told \xd7 what\'s actually written',mitoDoDia:'MYTH OF THE DAY',teContaram:'THE MYTH',fonteDiz:'THE SOURCE SAYS',recibo:'RECEIPTS',anterior:'Previous',proximo:'Next',compartilhar:'Share',voltarAoDia:'Back to today\'s myth',contador:'{n} of {total}',progresso:'You\'ve gone through {n} of {total} myths.',copiado:'Copied \u2014 paste it wherever you want.',naoCopiou:'Couldn\'t copy here \u2014 select the text and copy it.',marca:'cosmicguide.cloud'},compartilhar:{teContaram:'The myth:',fonteDiz:'The source says:',recibo:'Receipts:'},mitos:{'taro-egito':{oQueTeContaram:'Tarot comes from ancient Egypt \u2014 it\'s the Book of Thoth of the pharaohs.',oQueAFonteDiz:'The whole idea starts in one chapter of a French book from 1781, by Antoine Court de G\xe9belin \u2014 41 years before Champollion cracked the hieroglyphs. He had no way of reading a single line of Egyptian. Waite himself wrote in 1911 that there is no evidence whatsoever for the Egyptian origin.',fonte:'Le Monde primitif, vol. 8, "Du Jeu des Tarots" \u2014 Court de G\xe9belin, 1781',detalhe:'That deck they sell you as a secret of the pharaohs spent some 350 years as a gambling game on Italian tavern tables. Card reading as we know it is 245 years old: it began when Court de G\xe9belin published the Egyptian thesis in 1781 \u2014 and two years later Etteilla was selling the first method. Waite himself, in 1911, wrote that there is no evidence for the Egyptian origin.'},superlua:{oQueTeContaram:'"Supermoon" is a rare event astronomy has been announcing forever.',oQueAFonteDiz:'The term was coined by an astrologer, Richard Nolle, in a horoscope magazine in 1979. There is no official astronomical definition \u2014 the technical name is perigee-syzygy, and the difference in size is impossible to catch with the naked eye without a side-by-side comparison.',fonte:'Richard Nolle, Dell Horoscope magazine, 1979',detalhe:'Every "giant Supermoon" headline promises a show nobody can pick out with the naked eye \u2014 the difference is about 14% in diameter, visible only in photos placed side by side. The word isn\'t even astronomy\'s: it was coined by an astrologer, Richard Nolle, in a horoscope magazine in 1979. It only went viral in 2011.'},'luas-cheias-nomes':{oQueTeContaram:'"Wolf Moon", "Strawberry Moon"\u2026 those are ancient Indigenous names.',oQueAFonteDiz:"The standard list was published by the Maine Farmers' Almanac in the 1930s \u2014 a gathering of Algonquian, colonial English and Celtic sources \u2014 and the Old Farmer's Almanac trimmed it to one name per month. And it describes the farming year of the northeastern United States: south of the equator it lands with the wrong hemisphere.",fonte:"Maine Farmers' Almanac, 1930s",detalhe:'Notice that February\'s "Snow Moon" falls at the height of summer south of the equator \u2014 the name arrived pre-packed from the hemisphere up top. The famous list came out of an American farming almanac from the 1930s, a gathering of Algonquian, English and Celtic sources trimmed to one name per month.'},'oito-fases':{oQueTeContaram:'The 8 phases of the Moon, each with its own meaning, are ancient wisdom.',oQueAFonteDiz:'The psychological reading of the eight phases is Dane Rudhyar\'s \u2014 set out as eight soli-lunar types in The Lunation Cycle (1967), on an idea he had been developing since the 1930s-40s (The Astrology of Personality, 1936). The old division is a different one \u2014 Ptolemy works with four quarters, and describes qualities, not personality.',fonte:'Dane Rudhyar \u2014 The Astrology of Personality, 1936; The Lunation Cycle, 1967',detalhe:'The carousel with the eight Moon phases and a "how to use it" for each one has an author and a birth certificate. The one who set out the eight types with a psychological reading was Dane Rudhyar, in The Lunation Cycle (1967), on an idea he had been developing since the 1930s-40s. The old authors split the Moon into four quarters \u2014 Ptolemy described qualities, not personality.'},'quiromancia-milenar':{oQueTeContaram:'Reading palms is an ancient art \u2014 mounts, hand types, the marriage line.',oQueAFonteDiz:"The modern system is born in 1843 with D'Arpentigny (La Chirognomonie), fills out with Heron-Allen (1883) and becomes a manual with Benham (1900). And the four hand types by element are Fred Gettings', 1965.",fonte:"La Chirognomonie, D'Arpentigny, 1843 \xb7 The Laws of Scientific Hand Reading, Benham, 1900",detalhe:"The marriage line somebody traced on your palm at the beach is younger than photography. The whole package \u2014 mounts, hand types, lines with names \u2014 was assembled between 1843 and 1900, from D'Arpentigny to Benham. And the four hand types by element are from 1965, by Fred Gettings."},'borra-de-cafe':{oQueTeContaram:'Reading coffee grounds is an ancient Turkish tradition, with ancestral symbols.',oQueAFonteDiz:'Coffee only reaches Istanbul in the 16th century \u2014 the practice cannot be older than the drink. And the dictionary of symbols (snake = enmity, house = a move) is late-19th-century British parlor, pinned down by Cicely Kent in 1922.',fonte:'Tea-Cup Reading, "A Highland Seer", 1881 \xb7 Cicely Kent, 1922',detalhe:'There was no way a great-grandmother from a thousand years back was reading coffee grounds: the first coffeehouses in Istanbul date to 1555, and the practice cannot be older than the drink. The table of symbols, with the snake standing for enmity, was put together in British parlors between 1881 and 1922, as an afternoon-tea game.'},'saturno-mestre':{oQueTeContaram:'Saturn is the great teacher of the zodiac, the professor of lessons \u2014 always was.',oQueAFonteDiz:'Reading Saturn as teacher and maturity is Liz Greene, 1976. In the old sources Saturn is malefic, and the reading depends on the sect: Valens notes that well-placed malefics indicate "the greatest positions and success".',fonte:'Liz Greene, 1976 \xb7 counterpoint: Vettius Valens, Anthologies, 2nd century',detalhe:'The villain planet became the professor, and nobody noticed the swap. In the old sources Saturn is the greater malefic \u2014 and Valens even notes that, well placed in its own sect, it indicates "the greatest positions and success". The "great teacher who brings lessons" is a psychological rereading published by Liz Greene in 1976.'},'karma-astrologia':{oQueTeContaram:'Karma and past lives were always part of astrology.',oQueAFonteDiz:'They are not in Ptolemy, Valens, Firmicus, Bonatti or Lilly. They enter the West through Theosophy, from 1875 onward, imported from Indian vocabulary. And the North Node as "soul mission" is Martin Schulman, 1975.',fonte:'Theosophy, 1875 onward \xb7 Martin Schulman, Karmic Astrology, 1975',detalhe:'The "karmic debt" in your chart appears in no ancient author \u2014 not in the Greeks, not in the medievals, not in Lilly. That vocabulary enters Western astrology through Theosophy, founded in 1875. And the "North Node = soul mission" package comes from a book of 1975, by Martin Schulman.'},'porcentagem-compatibilidade':{oQueTeContaram:'There is a compatibility percentage between signs \u2014 "you two are an 87% match".',oQueAFonteDiz:'The number exists in no source at all \u2014 ancient, medieval or Renaissance. Ptolemy, Dorotheus, M\u0101sh\u0101\u02beall\u0101h and Lilly, all combed through: nothing. What the tradition has is a scale of four steps (Tetrabiblos IV.7), and in it a third of the sign pairs are "alien".',fonte:'No ancient source \u2014 a 20th-century commercial invention; the real scale: Ptolemy, Tetrabiblos IV.7, 2nd century',detalhe:'That "you two are 87% compatible" came out of no book \u2014 it came out of magazines and software from the last century. In the old source the yardstick is a different one, and harsher: Ptolemy sorts the relationships into four steps, and a third of the sign pairs he calls alien \u2014 they don\'t even see each other. A low score doesn\'t sell, so the market stopped showing it.'},'lua-azul':{oQueTeContaram:'"Blue Moon" is the second full moon in a month \u2014 the classic definition.',oQueAFonteDiz:"It is a documented misreading: in 1946 the amateur astronomer James Hugh Pruett got the Maine Farmers' Almanac rule wrong in Sky & Telescope (there it was the third full moon of a season with four). The magazine itself ran the correction in 1999. Neither of the two definitions is old.",fonte:'Sky & Telescope, James Hugh Pruett, 1946; the magazine\'s own correction, 1999',detalhe:'The definition everybody repeats was born from somebody misreading a magazine. In 1946 the amateur astronomer Pruett got the almanac rule wrong in Sky & Telescope; NPR repeated it in 1980 and Trivial Pursuit set it in stone in 1986. The magazine published the correction in 1999 \u2014 too late.'},'lua-de-sangue':{oQueTeContaram:'"Blood Moon" is an ancient biblical term for eclipses.',oQueAFonteDiz:'The image exists in Joel 2:31, but the term as the name of an eclipse comes from pastor Mark Biltz (2008) and John Hagee (Four Blood Moons, 2013). Astronomers don\'t use it.',fonte:'Mark Biltz, 2008 \xb7 John Hagee, Four Blood Moons, 2013',detalhe:'The name stamped on every eclipse headline is newer than the iPhone. As a label for a lunar eclipse, "Blood Moon" was launched by an American pastor in 2008 and turned into a best seller in 2013. The Bible has the poetic image in Joel \u2014 but it doesn\'t call an eclipse that.'},'mercurio-retrogrado':{oQueTeContaram:'Mercury retrograde breaks devices, takes down systems and sends the ex back.',oQueAFonteDiz:'The old source talks about delay: Valens writes that the retrograde "postpones expectations, actions and profits" and that the second station "cancels the delay". Nothing about technology, contracts or exes. The phrase doesn\'t even show up in the general press before 1996.',fonte:'Vettius Valens, Anthologies, 2nd century; press trail: 1996',detalhe:'The official culprit behind your frozen laptop has an alibi almost two thousand years old. What Valens wrote in the 2nd century was delay: the retrograde "postpones expectations, actions and profits" \u2014 nothing about devices, contracts or exes. The phrase only reaches the press from 1996 on.'},'leao-coracao':{oQueTeContaram:'Leo rules the heart \u2014 that\'s how it is in the ancient texts.',oQueAFonteDiz:'In the old Zodiac Man list (Manilius, Astronomica II), Leo gets the flanks and the shoulder blades \u2014 the heart belongs to the Sun, not to the sign. The oldest printable "Leo = heart" version is Agrippa\'s Scale of Twelve, 1533.',fonte:'Manilius, Astronomica II.453\u2013465, 1st century \xb7 Agrippa, 1533',detalhe:'Ask an astrology circle where "Leo rules the heart" comes from and nobody points to the book. In the oldest list of body and sign, Manilius gives Leo the flanks and the shoulder blades \u2014 the heart belonged to the Sun. The popular version only shows up in print in 1533, in Agrippa\'s Scale of Twelve.'},ofiuco:{oQueTeContaram:'There is a 13th sign, Ophiuchus, that they\'re hiding from you.',oQueAFonteDiz:'A sign was never a constellation. The zodiac has been twelve equal parts of 30\xb0 since the 5th century BC, and Ptolemy (Tetrabiblos I.22) says the signs are counted from the equinoxes and solstices "and from no other source". The IAU constellation boundaries are from 1930.',fonte:'Ptolemy, Tetrabiblos I.22, 2nd century \xb7 IAU constellation boundaries, 1930',detalhe:'Every so often the same headline comes back around: "NASA changed your sign". Except a sign is a 30\xb0 slice counted from the equinox, not a constellation drawing \u2014 it has been that way for some 2,450 years, and Ptolemy wrote that the signs are counted from the equinoxes "and from no other source". The constellation map that houses Ophiuchus was drawn by the IAU in 1930, for astronomical use.'},'urano-aquario':{oQueTeContaram:'Uranus rules Aquarius \u2014 classical rulership.',oQueAFonteDiz:'Uranus was discovered in 1781. In the tradition, Aquarius is the domicile of Saturn (Ptolemy, Tetrabiblos I.17). The attribution to Uranus begins in 1825 (Smith) and 1828 (Varley) \u2014 and in 1834 it was still being argued.',fonte:'Ptolemy, Tetrabiblos I.17, 2nd century; attribution to Uranus: Smith, 1825 / Varley, 1828',detalhe:'The "classical ruler" of Aquarius didn\'t even exist on the charts until the other day: Uranus was only discovered in 1781. In the tradition, Aquarius was always the house of Saturn. The swap begins around 1825 \u2014 and in 1834 there were still almanac readers asking why the new planet had no house at all.'},'estrela-esperanca':{oQueTeContaram:'The Star card was always the card of hope.',oQueAFonteDiz:'In the deck\'s own manual (Waite, 1911), the first reading of the Star is "loss, theft, privation, abandonment" \u2014 hope appears as a second reading, "another version". The priority was flipped over the course of the 20th century.',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'Open the original manual of the best-selling deck in the world and look up the Star: the first reading is "loss, theft, privation, abandonment". Hope is in there as "another version", in second place. It was the 20th century that promoted the second option to sole meaning \u2014 following the picture, not the text.'},'carta-invertida':{oQueTeContaram:'A reversed card means blockage or denial \u2014 traditional reading.',oQueAFonteDiz:'In Waite (1911) the reversal is usually a side meaning \u2014 sometimes better than the upright card: the Wheel of Fortune reversed is "increase, abundance"; the Emperor reversed is "benevolence, compassion, credit". The "blockage/excess" key is 20th century (Gray, Pollack, Greer).',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'Some cards get better upside down in the original manual: the Wheel of Fortune reversed becomes "increase, abundance", and the Emperor reversed, "benevolence, compassion". In Waite, 1911, the reversal is usually a side meaning \u2014 not a defect in the card. The rule "reversed = blockage" was written afterwards, over the course of the 20th century.'},'cruz-celta':{oQueTeContaram:'The Celtic Cross is an ancient Celtic spread.',oQueAFonteDiz:'The name is Waite\'s, 1911. The structure comes from Golden Dawn circles of the 1890s \u2014 and Waite says only that the spread "has been used in private for many years".',fonte:'A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'The most famous spread in tarot has nothing druid about it. The name "Celtic Cross" debuts in 1911, in Waite\'s manual, and the layout comes from the occultist circles of 1890s London. Celtic in name only.'},'marselha-o-mais-antigo':{oQueTeContaram:'The Tarot de Marseille is the original tarot, the oldest of them all.',oQueAFonteDiz:'It is a French printing pattern of the 17th\u201318th centuries (Noblet c. 1650, Conver 1760). The oldest tarots are the hand-painted Italian ones of the 15th century. And the name "Tarot de Marseille" was popularized by Paul Marteau, of the manufacturer Grimaud, in 1930.',fonte:'French pattern, 17th\u201318th centuries (Conver, 1760); the name: Paul Marteau, Grimaud, 1930',detalhe:'The "original tarot" is newer than the decks it claims to come before: the hand-painted Italian tarots come first, and the Marseille pattern is French printing of the 17th\u201318th centuries. Even the name is a commercial label: the one who christened "Tarot de Marseille" was the manufacturer Paul Marteau, in 1930.'},'astrologia-5000-anos':{oQueTeContaram:'Astrology is 5,000 years old.',oQueAFonteDiz:'What is ~4,000 years old are Mesopotamian state omens \u2014 a different thing. The zodiac is ~2,450 years old; the oldest individual horoscope is from 410 BC; the natal chart with Ascendant and houses is ~2,150 years old.',fonte:'Oldest cuneiform horoscope: 410 BC; Hellenistic natal chart: c. 150\u2013120 BC',detalhe:'The round number doubles the real age of the thing. What the Babylonians of 4,000 years ago were reading were state omens \u2014 rain, war, the king \u2014 not a person\'s chart. The first known individual horoscope is from 410 BC, and the natal chart with Ascendant and houses is some 2,150 years old.'},'horoscopo-de-jornal':{oQueTeContaram:'The daily horoscope by sign is astrology\'s classic format.',oQueAFonteDiz:'It has a premiere date: August 24, 1930, in the Sunday Express, by R. H. Naylor \u2014 about the birth of Princess Margaret. In 1930 the paper had to explain to its readers what a horoscope was.',fonte:'R. H. Naylor, Sunday Express, 24/08/1930',detalhe:'The horoscope in your feed has a premiere date like a soap opera: August 1930, in a British paper, about the birth of a princess. It was such a novelty that the paper had to explain to its readers what a horoscope was. In the tradition, the one who describes the individual is the Ascendant, not the Sun sign.'},'signo-personalidade':{oQueTeContaram:'"Aries is impulsive, Scorpio is intense" \u2014 the ancients already described them that way.',oQueAFonteDiz:'Characterology by Sun sign is 20th century: Alan Leo (c. 1895\u20131910) onward, popularized by Linda Goodman in 1968. In Ptolemy, character comes from Mercury and the Moon (Tetrabiblos III.13) \u2014 there is no chapter of "twelve personalities".',fonte:'Alan Leo, c. 1895\u20131910 \xb7 Linda Goodman, Sun Signs, 1968 \xb7 Ptolemy, Tetrabiblos III.13, 2nd century',detalhe:'The sketch of your sign \u2014 stubborn, dramatic, dreamy \u2014 is in no ancient author at all. That format is born with Alan Leo at the turn of the 20th century and blows up with Linda Goodman in 1968. Ptolemy read character in Mercury and in the Moon; and the portrait Valens draws of the signs is unrecognizable to anyone who reads horoscopes today.'},'numerologia-pitagoras':{oQueTeContaram:'The numerology table A=1, B=2\u2026 comes from Pythagoras.',oQueAFonteDiz:'Pythagoras left no writings, and the 26-letter alphabet is not his. The table in three columns of nine traces back to L. Dow Balliett, 1908 \u2014 the "master numbers" 11 and 22 are hers as well.',fonte:'L. Dow Balliett, 1908',detalhe:'The "Pythagoras method" uses an alphabet Pythagoras never saw \u2014 and he left no writings behind. The three-row table with the modern alphabet has its oldest trail in a book from 1908, by L. Dow Balliett, along with the master numbers 11 and 22. All that\'s left of the Greek is the name.'},'lua-nova-intencoes':{oQueTeContaram:'The New Moon is the moment to plant intentions \u2014 an ancestral ritual.',oQueAFonteDiz:'Planting FOR REAL on the dark moon is a primary source: Cato the Elder, 2nd century BC, "luna silente". "Planting intentions" is a modern transposition \u2014 Jan Spiller, New Moon Astrology, 2001.',fonte:'Cato the Elder, De Agri Cultura 40.1, 2nd century BC \xb7 Jan Spiller, New Moon Astrology, 2001',detalhe:'The planting part is Roman; the wish-list part is as old as Windows XP. Cato the Elder told farmers to sow with the dark moon \u2014 actual planting, in the ground. The New Moon intentions notebook comes from an American book of 2001, by Jan Spiller.'},'nao-e-previsao':{oQueTeContaram:'"It\'s not prediction, they\'re tendencies" \u2014 astrology\'s elegant old framing.',oQueAFonteDiz:'The phrase is born from a criminal defense: Alan Leo was prosecuted for fortune-telling in London in 1914 and 1917; the defense argument was that he described tendencies, not fortunes. It fell apart when the prosecution read out his almanac predicting a death in the family \u2014 he was convicted and fined \xa35.',fonte:'Alan Leo trials, London, 1914 and 1917',detalhe:'The most elegant phrase on the market was born in a courtroom. Alan Leo, prosecuted for fortune-telling in London, defended himself by saying he described tendencies, not fortunes \u2014 the prosecution read his almanac out loud, predicting a death in the family, and he was convicted in 1917. The whole market inherited the phrase without knowing where it came from.'}}}},1634,[]);